#!/bin/sh
# Generated by craftguild-standards-engine installer. Regenerate from craftguild.toml.
set -eu
command_name='craftguild-standards-engine'
repository='craftguild/standards.rs'
tag_prefix='v'
transport='curl'
version=''
version_set=0
bindir_set=0
uninstall=0
help=0
download=''
staged=''
privileged=0

fail() { printf '%s\n' "$*" >&2; exit 1; }
github() {
    # Reuse gh login or GH_TOKEN, pin the host and suppress credential-bearing diagnostics.
    GH_HOST=github.com GH_PROMPT_DISABLED=1 GH_PAGER=cat GH_DEBUG= DEBUG= gh "$@" 2>/dev/null
}
destination_op() {
    if [ "$privileged" = 1 ]; then sudo "$@"; else "$@"; fi
}
cleanup() {
    result=$?
    trap - 0 HUP INT TERM
    if [ -n "$staged" ]; then
        destination_op rm -f "$staged" || result=1
    fi
    if [ -n "$download" ]; then rm -rf "$download" || result=1; fi
    exit "$result"
}
trap cleanup 0
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM

stable_version() {
    # Reject leading zeros, suffixes, empty components and non-ASCII digits.
    printf '%s\n' "$1" | LC_ALL=C awk -F. '
        NR != 1 { exit 1 }
        NF != 3 { exit 1 }
        { for (i=1; i<=3; i++) if ($i !~ /^[0-9]+$/ || ($i ~ /^0/ && length($i)>1)) exit 1 }
    '
}
while [ "$#" -gt 0 ]; do
    case "$1" in
        --version)
            [ "$version_set" = 0 ] && [ "$#" -ge 2 ] || fail 'Invalid or duplicate --version'
            version=$2; version_set=1; shift 2 ;;
        --bindir)
            [ "$bindir_set" = 0 ] && [ "$#" -ge 2 ] || fail 'Invalid or duplicate --bindir'
            case "$2" in /*) ;; *) fail 'BINDIR must be a nonempty absolute path' ;; esac
            bindir=$2; bindir_set=1; shift 2 ;;
        --uninstall)
            [ "$uninstall" = 0 ] || fail 'Duplicate --uninstall'
            uninstall=1; shift ;;
        --help)
            [ "$help" = 0 ] || fail 'Duplicate --help'
            help=1; shift ;;
        *) fail "Unknown argument: $1" ;;
    esac
done
[ "$uninstall" = 0 ] || [ "$version_set" = 0 ] || fail '--uninstall cannot be combined with --version'
if [ "$version_set" = 1 ]; then
    stable_version "$version" || fail 'Version must be stable X.Y.Z without a tag prefix'
fi
if [ "$help" = 1 ]; then
    printf '%s\n' "Usage: sh install.sh [--version X.Y.Z] [--bindir DIR] [--uninstall] [--help]"
    exit 0
fi
if [ "$bindir_set" = 0 ]; then
    if [ "${BINDIR+x}" = x ]; then bindir=$BINDIR
    else
        [ -n "${HOME:-}" ] || fail 'HOME is required for the default destination'
        bindir=$HOME/.local/bin
    fi
fi
case "$bindir" in /*) ;; *) fail 'BINDIR must be a nonempty absolute path' ;; esac
destination=$bindir/$command_name

destination_privilege() {
    parent=$bindir
    while [ ! -e "$parent" ]; do parent=$(dirname "$parent"); done
    [ -d "$parent" ] || fail 'Destination ancestor is not a directory'
    if [ ! -w "$parent" ] && [ "$(id -u)" != 0 ]; then
        command -v sudo >/dev/null 2>&1 || fail 'sudo is required for destination operations'
        privileged=1
    fi
}
regular_destination() {
    [ ! -L "$destination" ] || fail 'Refusing a symlink at the command destination'
    if [ -e "$destination" ]; then
        [ -f "$destination" ] || fail 'Command destination is not a regular file'
    fi
}
regular_destination
if [ "$uninstall" = 1 ]; then
    if [ -f "$destination" ]; then
        destination_privilege
        destination_op rm -f "$destination"
    fi
    printf '%s\n' "Uninstalled $command_name from $bindir"
    exit 0
fi

case "$(uname -s)" in
    Darwin) system=apple-darwin ;;
    Linux) system=unknown-linux-gnu ;;
    *) fail 'Unsupported operating system' ;;
esac
case "$(uname -m)" in
    x86_64|amd64) architecture=x86_64 ;;
    arm64|aarch64) architecture=aarch64 ;;
    *) fail 'Unsupported architecture' ;;
esac
target=$architecture-$system
if [ "$transport" = github-cli ]; then
    command -v gh >/dev/null 2>&1 || fail 'GitHub CLI (gh) is required; use gh auth login or GH_TOKEN'
else command -v curl >/dev/null 2>&1 || fail 'curl is required'; fi
if command -v sha256sum >/dev/null 2>&1; then hash_tool=sha256sum
elif command -v shasum >/dev/null 2>&1; then hash_tool=shasum
else fail 'sha256sum or shasum is required'; fi
if [ "$version_set" = 0 ]; then
    if [ "$transport" = github-cli ]; then
        tag=$(github release view --repo "github.com/$repository" --json tagName --jq .tagName) \
            || fail 'GitHub Latest Release lookup failed; check authentication, repository access and connectivity'
    else
        latest=$(curl -fsSL --proto '=https' --proto-redir '=https' -o /dev/null -w '%{url_effective}' "https://github.com/$repository/releases/latest")
        case "$latest" in
            "https://github.com/$repository/releases/tag/"*) tag=${latest#"https://github.com/$repository/releases/tag/"} ;;
            *) fail 'Invalid Latest Release redirect; use --version X.Y.Z' ;;
        esac
    fi
    case "$tag" in
        "$tag_prefix"*) version=${tag#"$tag_prefix"} ;;
        *) fail 'Latest Release belongs to another group; use --version X.Y.Z' ;;
    esac
    stable_version "$version" || fail 'Latest Release is not a stable group version; use --version X.Y.Z'
else tag=$tag_prefix$version; fi
asset=$command_name-v$version-$target
download=$(mktemp -d "${TMPDIR:-/tmp}/$command_name-download.XXXXXX")
base=https://github.com/$repository/releases/download/$tag
if [ "$transport" = github-cli ]; then
    github release download "$tag" --repo "github.com/$repository" --dir "$download" \
        --pattern "$asset" --pattern "SHA256SUMS-$target.txt" >/dev/null \
        || fail 'GitHub Release asset download failed; check authentication, repository access and connectivity'
else
    curl -fsSL --proto '=https' --proto-redir '=https' "$base/$asset" -o "$download/$asset"
    curl -fsSL --proto '=https' --proto-redir '=https' "$base/SHA256SUMS-$target.txt" -o "$download/SHA256SUMS-$target.txt"
fi
expected=$(LC_ALL=C awk -v asset="$asset" '
    NF != 2 || length($1) != 64 || $1 ~ /[^0-9a-fA-F]/ { bad=1 }
    $2 == asset { count++; hash=tolower($1) }
    END { if (bad || count != 1) exit 1; print hash }
' "$download/SHA256SUMS-$target.txt") || fail 'Missing, duplicate or malformed checksum entry'
if [ "$hash_tool" = sha256sum ]; then
    actual=$(sha256sum "$download/$asset")
else actual=$(shasum -a 256 "$download/$asset"); fi
actual=${actual%% *}
[ "$actual" = "$expected" ] || fail 'SHA-256 mismatch'

# Only verified bytes reach destination operations; never execute the binary.
destination_privilege
destination_op mkdir -p "$bindir"
staged=$(destination_op mktemp "$bindir/.$command_name.XXXXXX")
destination_op cp "$download/$asset" "$staged"
destination_op chmod 0755 "$staged"
regular_destination
destination_op mv -f "$staged" "$destination"
staged=''
printf '%s\n' "Installed $command_name $version at $destination"
case ":${PATH:-}:" in
    *":$bindir:"*) ;;
    *) printf '%s\n' "Add $bindir to PATH in your shell; for example:" '  export PATH="/absolute/bin:$PATH"' ;;
esac
